        /// Check that <paramref name="value" /> is a <c>xs:dateTime</c> with
        /// the time zone set to UTC.
        /// </summary>
        public static bool IsXsDateTime(
            string value
        )
        {
            if (!MatchesXsDateTime(value))
            {
                return false;
            }

            return IsPrefixedWithValidDate(value);
        }

