            [CodeAnalysis.SuppressMessage("ReSharper", "NegativeEqualityExpression")]
            public override IEnumerable<Reporting.Error> TransformReference(
                Our.IReference that
            )
            {
                if (!(that.Keys.Count >= 1))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Keys must contain at least one item.");
                }

                if (!(
                    !(that.Keys.Count >= 1)
                    || Our.Constants.GloballyIdentifiables.Contains(Common.ListHelpers.At(that.Keys, 0).Type)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-121: For References the value of type of " +
                        "the first key of keys shall be one of Globally " +
                        "Identifiables.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ExternalReference
                        && that.Keys.Count >= 1
                    )
                    || Our.Constants.GenericGloballyIdentifiables.Contains(Common.ListHelpers.At(that.Keys, 0).Type)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-122: For external references the value of " +
                        "type of the first key of keys shall be one of Generic " +
                        "Globally Identifiables.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ModelReference
                        && that.Keys.Count >= 1
                    )
                    || Our.Constants.AasIdentifiables.Contains(Common.ListHelpers.At(that.Keys, 0).Type)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-123: For model references the value of type " +
                        "of the first key of keys shall be one of AAS identifiables.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ExternalReference
                        && that.Keys.Count >= 1
                    )
                    || (
                        Our.Constants.GenericGloballyIdentifiables.Contains(Common.ListHelpers.At(that.Keys, -1).Type)
                        || Our.Constants.GenericFragmentKeys.Contains(Common.ListHelpers.At(that.Keys, -1).Type)
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-124: For external references the last key " +
                        "of keys shall be either one of Generic Globally " +
                        "Identifiables or one of Generic Fragment Keys.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ModelReference
                        && that.Keys.Count > 1
                    )
                    || (
                        Enumerable.Range(
                            1,
                            System.Math.Max(0, that.Keys.Count - 1)
                        ).All(
                            i => Our.Constants.FragmentKeys.Contains(Common.ListHelpers.At(that.Keys, i).Type))
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-125: For model references with more than " +
                        "one key in keys the value of type of each of the keys " +
                        "following the first key of keys shall be one of Fragment " +
                        "Keys.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ModelReference
                        && that.Keys.Count > 1
                    )
                    || (
                        Enumerable.Range(
                            0,
                            that.Keys.Count - 1
                        ).All(
                            i => !Our.Constants.GenericFragmentKeys.Contains(Common.ListHelpers.At(that.Keys, i).Type))
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-126: For model references with more than " +
                        "one key in keys the value of type of the last key in " +
                        "the reference key chain may be one of Generic Fragment Keys " +
                        "or no key at all shall have a value out of Generic Fragment " +
                        "Keys.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ModelReference
                        && that.Keys.Count > 1
                        && Common.ListHelpers.At(that.Keys, -1).Type == KeyTypes.FragmentReference
                    )
                    || (
                        Common.ListHelpers.At(that.Keys, -2).Type == KeyTypes.File
                        || Common.ListHelpers.At(that.Keys, -2).Type == KeyTypes.Blob
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-127: For model references, with more than " +
                        "one key in keys a key with type Fragment Reference shall be " +
                        "preceded by a key with type File or Blob.");
                }

                if (!(
                    !(
                        that.Type == ReferenceTypes.ModelReference
                        && that.Keys.Count > 2
                    )
                    || (
                        Enumerable.Range(
                            0,
                            that.Keys.Count - 1
                        ).All(
                            i => !(Common.ListHelpers.At(that.Keys, i).Type == KeyTypes.SubmodelElementList)
                                || Verification.MatchesXsNonNegativeInteger(Common.ListHelpers.At(that.Keys, i + 1).Value))
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-128: For model references, the value of " +
                        "a key preceded by a key with type Submodel element list is " +
                        "an integer number denoting the position in the array of " +
                        "the submodel element list.");
                }

                foreach (var error in Verification.VerifyReferenceTypes(that.Type))
                {
                    error.PrependSegment(
                        new Reporting.NameSegment("type"));
                    yield return error;
                }

                if (that.ReferredSemanticId != null)
                {
                    foreach (var error in Verification.Verify(that.ReferredSemanticId))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("referredSemanticId"));
                        yield return error;
                    }
                }

                foreach (var error in Verification.Verify_ListOf_IKey(that.Keys))
                {
                    error.PrependSegment(
                        new Reporting.NameSegment("keys"));
                    yield return error;
                }
            }

