            [CodeAnalysis.SuppressMessage("ReSharper", "NegativeEqualityExpression")]
            public override IEnumerable<Reporting.Error> TransformDataSpecificationIec61360(
                Our.IDataSpecificationIec61360 that
            )
            {
                if (!(
                    !((that.Value != null)
                    && (that.ValueList != null))))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASc-3a-010: If value is not empty then value " +
                        "list shall be empty and vice versa.");
                }

                if (!(
                    !(
                        (that.DataType != null)
                        && Our.Constants.Iec61360DataTypesWithUnit.Contains(that.DataType!.Value)
                    )
                    || (
                        (that.Unit != null)
                        || (that.UnitId != null)
                    )))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASc-3a-009: If data type is a an integer, real " +
                        "or rational with a measure or currency, unit or unit ID " +
                        "shall be defined.");
                }

                if (!(
                    !(that.Definition != null)
                    || (that.Definition!.Count >= 1)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Definition must be either not set or have at least one item.");
                }

                if (!(
                    !(that.Definition != null)
                    || Verification.LangStringsHaveUniqueLanguages(that.Definition!)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Definition must specify unique languages.");
                }

                if (!(
                    !(that.ShortName != null)
                    || (that.ShortName!.Count >= 1)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Short name must be either not set or have at least one item.");
                }

                if (!(
                    !(that.ShortName != null)
                    || Verification.LangStringsHaveUniqueLanguages(that.ShortName!)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Short name must specify unique languages.");
                }

                if (!(that.PreferredName.Count >= 1))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Preferred name must have at least one item.");
                }

                if (!(
                    Verification.LangStringsHaveUniqueLanguages(that.PreferredName)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Preferred name must specify unique languages.");
                }

                if (!(
                    that.PreferredName.Any(
                        langString => Verification.IsBcp47ForEnglish(langString.Language))))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASc-3a-002: preferred name shall be provided at " +
                        "least in English.");
                }

                foreach (
                    var error in Verification.Verify_ListOf_ILangStringPreferredNameTypeIec61360(
                        that.PreferredName))
                {
                    error.PrependSegment(
                        new Reporting.NameSegment("preferredName"));
                    yield return error;
                }

                if (that.ShortName != null)
                {
                    foreach (
                        var error in Verification.Verify_ListOf_ILangStringShortNameTypeIec61360(
                            that.ShortName))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("shortName"));
                        yield return error;
                    }
                }

                if (that.Unit != null)
                {
                    foreach (
                        var error in Verification.VerifyNonEmptyXmlSerializableString(
                            that.Unit))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("unit"));
                        yield return error;
                    }
                }

                if (that.UnitId != null)
                {
                    foreach (var error in Verification.Verify(that.UnitId))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("unitId"));
                        yield return error;
                    }
                }

                if (that.SourceOfDefinition != null)
                {
                    foreach (
                        var error in Verification.VerifyNonEmptyXmlSerializableString(
                            that.SourceOfDefinition))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("sourceOfDefinition"));
                        yield return error;
                    }
                }

                if (that.Symbol != null)
                {
                    foreach (
                        var error in Verification.VerifyNonEmptyXmlSerializableString(
                            that.Symbol))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("symbol"));
                        yield return error;
                    }
                }

                if (that.DataType.HasValue)
                {
                    foreach (
                        var error in Verification.VerifyDataTypeIec61360(
                            that.DataType.Value))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("dataType"));
                        yield return error;
                    }
                }

                if (that.Definition != null)
                {
                    foreach (
                        var error in Verification.Verify_ListOf_ILangStringDefinitionTypeIec61360(
                            that.Definition))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("definition"));
                        yield return error;
                    }
                }

                if (that.ValueFormat != null)
                {
                    foreach (
                        var error in Verification.VerifyNonEmptyXmlSerializableString(
                            that.ValueFormat))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("valueFormat"));
                        yield return error;
                    }
                }

                if (that.ValueList != null)
                {
                    foreach (var error in Verification.Verify(that.ValueList))
